async function GET_OBJECT(tbl, vrb = true) {
  let bits = 0, len = 0, xbits = 0, tlen = 0, gcheck = false, olen = 0, obj = 0;
  xbits = g.P_SLOCBITS;
  tlen = get(tbl, g.P_MATCHLEN);
  if (btst(g.P_GETFLAGS, P_INHIBIT)) {
    return true;
  }
  if (!g.P_NAM && g.P_ADJ) {
    if (await WT$(g.P_ADJN, PS$OBJECT, P1$OBJECT)) {
      g.P_NAM = g.P_ADJN;
      g.P_ADJ = false;
    } else if (await NULL_F()) {
    }
  }
  if (!g.P_NAM && !g.P_ADJ && !(g.P_GETFLAGS == P_ALL) && (g.P_GWIMBIT == 0)) {
    if (vrb) {
      tell("There seems to be a noun missing in that sentence!\n");
    }
    return false;
  }
  if (!(g.P_GETFLAGS == P_ALL) || (g.P_SLOCBITS == 0)) {
    g.P_SLOCBITS = -1;
  }
  g.P_TABLE = tbl;
  loop1: for (;;) {
    if (gcheck) {
      await GLOBAL_CHECK(tbl);
    } else {
      if (g.LIT) {
        clearFlag(PLAYER, TRANSBIT);
        await DO_SL(g.HERE, SOG, SIR);
        setFlag(PLAYER, TRANSBIT);
      }
      await DO_SL(PLAYER, SH, SC);
      if (eq(get(tbl, 0), tlen)) {
        if (g.P_ADJ && (g.P_NAM == W.SPELL || g.P_NAM == false)) {
          g.P_NAM = g.P_ADJN;
        }
        await SPELL_CHECK(tbl, g.P_NAM);
      }
    }
    len = get(tbl, g.P_MATCHLEN) - tlen;
    if (btst(g.P_GETFLAGS, P_ALL)) {
    } else if (btst(g.P_GETFLAGS, P_ONE) && !(len == 0)) {
      if (!(len == 1)) {
        put(tbl, 1, get(tbl, random(len)));
        tell("(How about the ");
        printD(get(tbl, 1));
        tell("?)\n");
      }
      put(tbl, g.P_MATCHLEN, 1);
    } else if ((len > 1) || ((len == 0) && !(g.P_SLOCBITS == (-1)))) {
      if (g.P_SLOCBITS == (-1)) {
        g.P_SLOCBITS = xbits;
        olen = len;
        put(tbl, g.P_MATCHLEN, get(tbl, g.P_MATCHLEN) - len);
        continue loop1;
      } else {
        if (len == 0) {
          len = olen;
        }
        if (!(g.WINNER == PLAYER)) {
          await CANT_ORPHAN();
          return false;
        } else if (vrb && g.P_NAM) {
          await WHICH_PRINT(tlen, len, tbl);
          g.P_ACLAUSE = tbl == g.P_PRSO ? P_NC1 : P_NC2;
          g.P_AADJ = g.P_ADJ;
          g.P_ANAM = g.P_NAM;
          await ORPHAN(false, false);
          g.P_OFLAG = true;
        } else if (vrb) {
          tell("There seems to be a noun missing in that sentence!\n");
        }
        g.P_NAM = false;
        g.P_ADJ = false;
        return false;
      }
    }
    if ((len == 0) && gcheck) {
      if (vrb) {
        g.P_SLOCBITS = xbits;
        if (g.LIT || isVerb(V.TELL)) {
          await OBJ_FOUND(NOT_HERE_OBJECT, tbl);
          g.P_XNAM = g.P_NAM;
          g.P_XADJ = g.P_ADJ;
          g.P_XADJN = g.P_ADJN;
          g.P_NAM = false;
          g.P_ADJ = false;
          g.P_ADJN = false;
          return true;
        } else {
          tell("It's too dark to see!\n");
        }
      }
      g.P_NAM = false;
      g.P_ADJ = false;
      return false;
    } else if (len == 0) {
      gcheck = true;
      continue loop1;
    }
    g.P_SLOCBITS = xbits;
    g.P_NAM = false;
    g.P_ADJ = false;
    return true;
  }
}

