async function GOTO(rm, v$ = true) {
  let olit = 0, ohere = 0;
  ohere = g.HERE;
  olit = g.LIT;
  move(g.WINNER, rm);
  g.HERE = rm;
  g.LIT = await LIT$(g.HERE);
  if ((g.WINNER == PLAYER) && !olit && !g.LIT && (85 > random(100))) {
    (await JIGS_UP("Oh, no! Something slithered alongside you and feasted on your person!"));
    return true;
  }
  await apply(getProp(g.HERE, P.ACTION), M_ENTER);
  if (g.WINNER == PLAYER) {
    g.ADV_OLD_LOC = false;
    if ((loc(ADVENTURER) == ohere) && g.ADVENTURER_CHARMED && (await WINNER_HAS_TREASURE$()) && !(g.HERE == T_A || g.HERE == TEMPLE || g.HERE == CLOSET) && !(g.HERE == WEST_CASTLE)) {
      tell("The adventurer, proceeding cautiously, follows you. He seems to be paying particular attention to your possessions.\n\n");
      move(ADVENTURER, g.HERE);
      g.ADVENTURER_STAY = true;
    }
  }
  if (!(g.HERE == rm)) {
    return true;
  } else if (!(PLAYER == g.WINNER)) {
    if (!(g.HERE == CLOSET || g.HERE == ENGINE_ROOM) && (loc(PLAYER) == ohere)) {
      tell("The ", D(g.WINNER), ", ever the good friend, leaves you.\n");
    } else if (!(g.HERE == CLOSET || g.HERE == ENGINE_ROOM) && (loc(PLAYER) == g.HERE)) {
      tell("The ", D(g.WINNER), " returns to you.\n");
    }
  } else if (v$) {
    await V_FIRST_LOOK();
  }
  return true;
}

