async function ROB(who, where = false, hide$ = false) {
  let n_ = 0, x = 0, robbed$ = false;
  x = first(who);
  for (;;) {
    if (!x) {
      return robbed$;
    }
    n_ = next(x);
    if (await RIPOFF(x, where)) {
      if (hide$) {
        setFlag(x, NDESCBIT);
      }
      robbed$ = x;
    }
    x = n_;
  }
}

async function BLT(who, where) {
  let n_ = 0, x = 0, cnt = 0;
  x = first(who);
  for (;;) {
    if (!x) {
      return cnt;
    }
    n_ = next(x);
    move(x, where);
    cnt = cnt + 1;
    x = n_;
  }
}

async function RIPOFF(x, where) {
  if (!(hasFlag(x, INVISIBLE)) && !(hasFlag(x, SCROLLBIT)) && !(x == BREAD || x == JUG) && hasFlag(x, TOUCHBIT) && hasFlag(x, TAKEBIT)) {
    if (x == STRONG_BOX) {
      return false;
    } else if (where && (loc(x) == where)) {
      return false;
    } else if (where) {
      move(x, where);
    } else {
      remove(x);
    }
    return true;
  } else {
    return false;
  }
}

