async function WATER_FUNCTION() {
  let av = 0, w_ = 0, pi$ = 0;
  if (isVerb(V.EXAMINE) && (g.PRSO == GLOBAL_WATER)) {
    if (g.HERE == BEACH) {
      tell("The ocean streches out as far as the eye can see to the south and east.\n");
    } else if (g.HERE == FOREST_2) {
      tell("The water is dark and murky, and lily pads cover most of the surface. I wouldn't drink the stuff.\n");
    } else {
      tell("The brook runs slowly through thick vegetation.\n");
    }
    return true;
  } else if (isVerb(V.THROUGH) && (g.PRSO == GLOBAL_WATER)) {
    tell("You have better things to do with your time than go swimming.\n");
    return true;
  } else if (isVerb(V.DRINK_FROM) && (g.PRSO == GLOBAL_WATER)) {
    await V_DRINK_FROM();
    return true;
  } else if (isVerb(V.SGIVE)) {
    return false;
  } else if (isVerb(V.THROUGH)) {
    tell("Swimming here is fraught with peril.\n");
    return true;
  } else if (isVerb(V.FILL)) {
    w_ = g.PRSI;
    g.PRSA = V.PUT;
    g.PRSI = g.PRSO;
    g.PRSO = w_;
    pi$ = false;
  } else if (g.PRSO == GLOBAL_WATER || g.PRSO == WATER) {
    w_ = g.PRSO;
    pi$ = false;
  } else {
    w_ = g.PRSI;
    pi$ = true;
  }
  if (w_ == GLOBAL_WATER) {
    if (isVerb(V.DRINK)) {
      return false;
    }
    w_ = WATER;
    if (isVerb(V.TAKE, V.PUT)) {
      remove(w_);
    }
  }
  if (pi$) {
    g.PRSI = w_;
  } else {
    g.PRSO = w_;
  }
  av = loc(g.WINNER);
  if (isVerb(V.TAKE, V.PUT) && !pi$) {
    if (g.PRSI && !(g.PRSI == JUG)) {
      if (g.PRSI == SEA || g.PRSI == GLOBAL_WATER) {
        tell("Ok, but there was plenty enough there already.\n");
        return remove(w_);
      } else if (getProp(g.PRSI, P.CAPACITY)) {
        tell("The water leaks out of the ", D(g.PRSI), " and evaporates immediately.\n");
        return remove(w_);
      } else {
        tell("The ", D(g.PRSI), " isn't a very good container.\n");
        return true;
      }
    } else if (loc(JUG) == g.WINNER) {
      if (!(hasFlag(JUG, OPENBIT))) {
        tell("The jug is closed.\n");
        return true;
      } else if (await GLOBAL_IN$(GLOBAL_WATER, g.HERE)) {
        if (!(loc(WATER) == JUG) || (getProp(WATER, P.SIZE) < 4)) {
          move(WATER, JUG);
          putProp(WATER, P.SIZE, 4);
          tell("The jug is now full of ");
          if (g.HERE == BEACH) {
            setFlag(WATER, RMUNGBIT);
            tell("sea");
          } else if (g.HERE == FOREST_2) {
            setFlag(WATER, RMUNGBIT);
            tell("foul algae-infested ");
          } else {
            clearFlag(WATER, RMUNGBIT);
          }
          tell("water.\n");
          return true;
        } else {
          tell("The jug is already full.\n");
          return true;
        }
      } else {
        tell("The only water here is in the jug.\n");
        return true;
      }
    } else if ((loc(g.PRSO) == JUG) && isVerb(V.TAKE) && !g.PRSI) {
      g.PRSO = JUG;
      await ITAKE();
      return g.PRSO = w_;
    } else {
      tell("The water slips through your fingers.\n");
      return true;
    }
  } else if (pi$) {
    tell("Nice try.\n");
    return true;
  } else if (isVerb(V.DROP, V.GIVE)) {
    remove(WATER);
    if (g.PRSI == SEA || g.PRSI == GLOBAL_WATER) {
      tell("Ok, but there was plenty enough there already.\n");
      return true;
    } else {
      tell("The water spills to the ground and evaporates.\n");
      return true;
    }
  } else if (isVerb(V.POUR_ON)) {
    remove(WATER);
    tell("The water cascades off the ", D(g.PRSI), " and onto the ground.\n");
    return true;
  } else if (isVerb(V.THROW)) {
    tell("The water splashes over everything and evaporates.\n");
    return remove(WATER);
  } else {
    return false;
  }
}

