async function TMAZE_F(rarg) {
  let tbl = 0, nex = 0, flg = false, offs = 0, plu = false;
  if ((loc(BANISH_SCROLL) == g.WINNER) && (g.HERE == T_A) && g.TERROR_TRAPPED && (g.TERROR_POINT > 0)) {
    tell("You hear a horrible anguished scream through the walls of the cavern as the terror realizes that it is trapped and its scroll of power stolen!\n\n");
    g.SCORE = g.SCORE + g.TERROR_POINT;
    g.TERROR_POINT = 0;
  }
  if (rarg == M_LOOK) {
    tell("This is a peculiar room, whose cream-colored walls are thin and translucent.\n");
    tbl = getProp(g.HERE, P.TMAZE);
    loop1: for (;;) {
      if (eq(get(tbl, offs), -1)) {
        break loop1;
      } else if (eq(get(tbl, offs + 1), 1)) {
        nex = nex + 1;
      }
      offs = offs + 2;
    }
    if (nex == 0) {
      tell("There is not a single exit from this place.\n");
      return true;
    } else if (nex == 1) {
      tell("An exit is");
    } else {
      plu = true;
      tell("Passages go");
    }
    tell(" to the ");
    offs = 0;
    loop2: for (;;) {
      if (eq(get(tbl, offs), -1)) {
        break loop2;
      } else if (eq(get(tbl, offs + 1), 1)) {
        tell(S(get(g.TMAZE_DIRS, div(offs, 2))));
        if (nex > 2) {
          flg = true;
          tell(", ");
        } else if (nex == 2) {
          if (flg) {
            tell(",");
          }
          tell(" and ");
        }
        nex = nex - 1;
      }
      offs = offs + 2;
    }
    tell(" and ");
    if (plu) {
      tell("they are");
    } else {
      tell("it is");
    }
    tell(" very strange indeed, perfectly round and black as pitch.\n");
    return true;
  } else if (rarg == M_BEG) {
    if (loc(TERROR) == g.HERE) {
      if (isVerb(V.WALK)) {
        tell("Your feet are leaden with fear, and cold sweat runs down your back as you make your way to the door, but you make no progress. Your mind tells you you are running, but you aren't getting anywhere.\n");
        return true;
      } else {
        return false;
      }
    } else if (isVerb(V.WALK)) {
      if ((g.HERE == T_A) && (g.PRSO == P.UP)) {
        await GOTO(DUNGEON);
        return true;
      } else if ((g.PRSO > P.UP) && eq(get(tbl = getProp(g.HERE, P.TMAZE), offs = ((g.PRSO - P.UP) * 2) - 1), 1)) {
        await GOTO(get(tbl, offs - 1));
        if (loc(TERROR) == g.HERE) {
          tell("An evil presence pervades the room, its source unseen. Fear seeps into your mind, like fog. You look fearfully around. There is something horrible here.\n");
        } else if (await CONNECTED$(g.HERE, loc(TERROR))) {
          tell("You sense that near this place an evil presence lurks. It seems close by and is moving.\n");
        }
        return true;
      } else {
        tell("You can't go that way.\n");
        return true;
      }
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function END_OF_WORLD() {
  tell("You suddenly feel weak and your knees buckle. Just as you collapse to the ground, you find yourself in the presence of the Circle. They seem tense and frightened and ask desperately about your recent doings. As you tell your tale of the map and pencil, they recoil in horror. \"The Terror is released!\" cries one. Belboz sinks into his throne. \"We are doomed!\" he gasps. One by one, the wizards flee to prepare a hopeless defense.\n");
  g.SCORE = -10;
  return await FINISH();
}

