async function PRE_QUICK_CAST() {
  let mem$ = 0, spell = 0, scroll = 0;
  if (isVerb(V.GNUSTO)) {
    spell = WRITE_MAGIC_SPELL;
  } else if (isVerb(V.FROTZ)) {
    spell = LIGHT_SPELL;
  } else if (isVerb(V.OZMOO)) {
    spell = CHEAT_DEATH_SPELL;
  } else if (isVerb(V.ZIFMIA)) {
    spell = SUMMON_SPELL;
  } else if (isVerb(V.VAXUM)) {
    spell = CHARM_SPELL;
  } else if (isVerb(V.REZROV)) {
    spell = OPEN_SPELL;
  } else if (isVerb(V.NITFOL)) {
    spell = TALK_TO_ANIMALS_SPELL;
  } else if (isVerb(V.EXEX)) {
    spell = HASTE_SPELL;
  } else if (isVerb(V.KULCAD)) {
    spell = DISPEL_SPELL;
  } else if (isVerb(V.MELBOR)) {
    spell = PROTECTION_SPELL;
  } else if (isVerb(V.BLORB)) {
    spell = STRONG_BOX_SPELL;
  } else if (isVerb(V.GUNCHO)) {
    spell = BANISH_SPELL;
  } else if (isVerb(V.GONDAR)) {
    spell = QUENCH_SPELL;
  } else if (isVerb(V.KREBF)) {
    spell = REPAIR_SPELL;
  } else if (isVerb(V.CLEESH)) {
    spell = NEWT_SPELL;
  } else if (isVerb(V.IZYUK)) {
    spell = FLY_SPELL;
  } else if (isVerb(V.FILFRE)) {
    spell = CREDITS_SPELL;
  } else {
    tell("**OOOPS!**\n");
    return true;
  }
  if (hasFlag(spell, RMUNGBIT)) {
    tell("The spell is defaced beyond recognition.\n");
    return true;
  }
  scroll = loc(spell);
  if (scroll && hasFlag(scroll, SCROLLBIT)) {
    if (loc(scroll) == g.WINNER) {
      remove(scroll);
      if (!(g.PRSO == KRILL)) {
        tell("As you cast the spell, the ", D(scroll), " vanishes!\n");
      }
      putProp(spell, P.COUNT, 1);
    } else if (hasFlag(spell, TOUCHBIT) || (loc(scroll) == g.HERE)) {
      tell("You don't have the ", D(spell), " memorized, nor do you have the scroll on which it is written.\n");
      return true;
    } else {
      tell("The ", D(spell), " is not committed to memory, and you haven't seen any scroll on which it is written.\n");
      return true;
    }
  }
  mem$ = getProp(spell, P.COUNT);
  if (spell == WRITE_MAGIC_SPELL) {
    return false;
  } else if (!(mem$ > 0)) {
    tell("You don't have the ", D(spell), " committed to memory!\n");
    return true;
  } else {
    putProp(spell, P.COUNT, mem$ - 1);
    g.SPELL_ROOM = g.SPELL_ROOM + 1;
    if (isVerb(V.KULCAD, V.GUNCHO)) {
      enable(await QUEUE(MORE_PROBE.id, 1));
    }
    return false;
  }
}

async function SCROLL_F() {
  let spell = 0;
  if (isVerb(V.TAKE)) {
    spell = first(g.PRSO);
    setFlag(spell, TOUCHBIT);
    return false;
  } else if (isVerb(V.CUT) && (g.PRSI == MAGIC_KNIFE)) {
    remove(g.PRSO);
    tell("The magic dagger reduces the scroll to shreds. The shreds shrivel up into tiny spitballs. The spitballs evaporate.\n");
    return true;
  } else if (isVerb(V.BURN) && (g.PRSI == ETERNAL_FLAME)) {
    remove(g.PRSO);
    tell("The ", D(g.PRSO), " burns cheerily. Interestingly, the flame is sort of purple and rather bright. Not even ashes remain.\n");
    return true;
  } else if (isVerb(V.EXAMINE, V.READ)) {
    if (spell = first(g.PRSO)) {
      if (hasFlag(spell, RMUNGBIT)) {
        tell("The scroll is defaced. The spell on it cannot be read.\n");
        return true;
      }
      tell("The scroll reads \"", D(spell), ": ", S(getProp(spell, P.TEXT)), "\".");
      if (spell == BANISH_SPELL || spell == DISPEL_SPELL) {
        tell(" The spell seems very long and extremely complicated.");
      }
      return crlf();
    } else {
      tell("Nothing useful can be made out on the scroll.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function SPELL_F() {
  let mem$ = 0, forget = false;
  let $1;
  if (isVerb(V.READ)) {
    if (!(loc(g.PRSO) == SPELL_BOOK) && !(loc(loc(g.PRSO)) == g.WINNER)) {
      tell("You can't do that without having the spell in your book or on a scroll in your hand.\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.MEMORIZE, V.LEARN)) {
    if (!(loc(g.PRSO) == SPELL_BOOK)) {
      if (loc(loc(g.PRSO)) == g.WINNER) {
        tell("You haven't written that spell into your book yet. Until you do, you can't memorize the spell.\n");
        return true;
      } else {
        return await V_LEARN();
      }
    } else if (!(loc(SPELL_BOOK) == g.WINNER)) {
      tell("You don't have your spell book. How do you expect to memorize a spell without a spell book?\n");
      return true;
    } else if (g.PRSO == WRITE_MAGIC_SPELL) {
      tell("You already know that spell by heart.\n");
      return true;
    } else if (!g.LIT) {
      tell("It will be hard to learn that spell in the dark.\n");
      return true;
    } else {
      mem$ = getProp(g.PRSO, P.COUNT);
      if (g.SPELL_ROOM == 0) {
        if (g.SPELL_MAX == 1) {
          tell("You can't concentrate well enough to learn the spell.\n");
          return true;
        } else if (mem$ == g.SPELL_MAX) {
        } else {
          await FORGET_SPELL(g.PRSO);
          mem$ = mem$ + 1;
          putProp(g.PRSO, P.COUNT, mem$);
          forget = true;
        }
      } else {
        g.SPELL_ROOM = g.SPELL_ROOM - 1;
        mem$ = mem$ + 1;
        putProp(g.PRSO, P.COUNT, mem$);
      }
      tell("Using your best study habits, you learn the ", D(g.PRSO));
      if (mem$ > 1) {
        tell(" yet another time");
      }
      tell(".\n");
      if (forget) {
        tell("You have so much buzzing around in your head, though, that it's likely that something may have been forgotten in the shuffle.\n");
      }
      return true;
    }
  } else if (isVerb(V.TAKE, V.DROP)) {
    $1 = await PICK_ONE(g.YUKS);
    tell(S($1));
    tell("\n");
    return true;
  } else {
    return false;
  }
}

async function FORGET_SPELL(spl) {
  let nspl = 0, f = 0, cnt = 0, tbl = 0, num = 0, sp = false;
  f = first(SPELL_BOOK);
  tbl = g.FORGET_TBL;
  loop1: for (;;) {
    if (!f) {
      break loop1;
    } else if ((cnt = getProp(f, P.COUNT)) > 0) {
      loop2: for (;;) {
        sp = f;
        put(tbl, 1, f);
        num = num + 1;
        tbl = tbl + 2;
        if ((cnt = cnt - 1) < 1) {
          break loop2;
        }
      }
    }
    f = next(f);
  }
  if ((num > 0) && eq(getProp(sp, P.COUNT), num)) {
    putProp(sp, P.COUNT, num - 1);
    return true;
  }
  put(g.FORGET_TBL, 0, num);
  if (num == 0) {
    return true;
  }
  for (;;) {
    if (!(eq(nspl = await RANDOM_ELEMENT(g.FORGET_TBL), spl))) {
      putProp(nspl, P.COUNT, getProp(nspl, P.COUNT) - 1);
      return true;
    }
  }
}

async function FORGET_ALL() {
  let f = 0;
  g.SPELL_ROOM = g.SPELL_MAX;
  f = first(SPELL_BOOK);
  for (;;) {
    if (!f) {
      return true;
    } else {
      putProp(f, P.COUNT, 0);
      f = next(f);
    }
  }
}

