async function HOVEL_KLUDGE() {
  tell("It is dark and smoky in here, but this is a place of great disorder, and its odor is indescribable. A pile of rags sits near a small pot which is bubbling and steaming over a tiny fire. The pile of rags sports a gnarled hand which busies itself with the noisome stew. A closer look reveals a withered crone at the other end of the hand.\n");
  if (g.CRONE_MOVE == 0) {
    tell("\nThe creature looks you over keenly and speaks: \"I should have thought they would send someone more ... more ...\" She laughs in an unsettling way. \"They've all left! A great storm is brewing in the east, my friend, and all have fled before it!\" She starts to chuckle. \"Take this and begone!\" With a wave of her hand, you find yourself reeling out of the door of the hovel, holding some sort of scroll in your hand.\n");
    move(OPEN_SCROLL, g.WINNER);
    g.CRONE_MOVE = g.MOVES;
  } else if ((g.MOVES - g.CRONE_MOVE) < 20) {
    tell("As you enter the crone's hovel, she booms at you: \"Are you here again? What a wizard!\" Her emphasis on the word \"wizard\" is filled with derision. \"Make a small effort, would you, to make your Circle proud of you?\" The same horrible emphasis on \"proud\" fills you with revulsion. \"Go!\" You find yourself back in the village.\n");
  } else {
    g.CRONE_MOVE = g.MOVES;
    tell("As you enter, the woman in rags wags her head slowly. \"You've returned, have you? You need help perhaps? Well, I've given you all the help in my meager store. You want more? Leave me!\" You find yourself in the village.\n");
  }
  return false;
}

