async function LONG_ROAD_EXIT_F() {
  if ((g.ROAD_LOC == ROAD_START) && (g.PRSO == P.EAST)) {
    return WEST_FORK;
  } else {
    clearFlag(LONG_ROAD, TOUCHBIT);
    await ROAD_TO_TABLE(g.ROAD_LOC);
    if (g.PRSO == P.WEST) {
      g.ROAD_LOC = g.ROAD_LOC + 1;
    } else if (g.PRSO == P.EAST) {
      g.ROAD_LOC = g.ROAD_LOC - 1;
    }
    await TABLE_TO_ROAD(g.ROAD_LOC);
    return LONG_ROAD;
  }
}

async function ROAD_TO_TABLE(sloc) {
  let tbl = 0, cnt = 0, f = first(LONG_ROAD), n_ = 0;
  tbl = g.ROAD_TABLE;
  for (;;) {
    if (f) {
      n_ = next(f);
    } else {
      return true;
    }
    if (f == g.WINNER) {
    } else if (hasFlag(f, TAKEBIT)) {
      loop2: for (;;) {
        if (eq(get(tbl, cnt), 0)) {
          put(tbl, cnt, sloc);
          put(tbl, cnt + 1, f);
          cnt = cnt + 2;
          remove(f);
          break loop2;
        } else {
          cnt = cnt + 2;
        }
      }
    }
    f = n_;
  }
}

async function TABLE_TO_ROAD(sloc) {
  let tbl = 0, cnt = 0;
  tbl = g.ROAD_TABLE;
  for (;;) {
    if (!(cnt < ROAD_TABLE_LENGTH)) {
      return true;
    } else if (eq(get(tbl, cnt), sloc)) {
      put(tbl, cnt, 0);
      move(get(tbl, cnt + 1), LONG_ROAD);
    }
    cnt = cnt + 2;
  }
}

async function ROAD_F() {
  if (isVerb(V.FOLLOW, V.TAKE)) {
    tell("You should supply a compass direction in which to follow the path.\n");
    return true;
  } else if (isVerb(V.DROP)) {
    if (await OUTSIDE$(g.HERE)) {
      tell("It's much safer to stay on the path, especially in these times.\n");
      return true;
    } else {
      tell("You'll have to give a direction.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function HILLS_F() {
  if (isVerb(V.EXAMINE)) {
    tell("The hills are mostly low and shrouded in a fine mist-like haze. They stretch out mainly to the west.\n");
    return true;
  } else if (isVerb(V.CLIMB_UP, V.CLIMB_FOO)) {
    await PERFORM(V.LEAVE, ROAD);
    return true;
  } else {
    return false;
  }
}

async function MOUNTAIN_F() {
  if (isVerb(V.LEAP) && (g.HERE == VISTA)) {
    return (await JIGS_UP("You execute a perfect swan-dive into the rocks below."));
  } else if (isVerb(V.CLIMB_FOO, V.CLIMB_UP)) {
    if (g.HERE == VISTA) {
      tell("You are here!\n");
      return true;
    } else if (g.HERE == VILLAGE || g.HERE == MOUNTAIN_TRAIL) {
      return await DO_WALK(P.UP);
    } else {
      tell("There's no way up the mountain from here.\n");
      return true;
    }
  } else if (isVerb(V.EXAMINE)) {
    tell("The mountain is tall and proud, and its shining peak stands above the low-hanging clouds.\n");
    return true;
  } else {
    return false;
  }
}

async function OUTSIDE$(rm) {
  if (!(hasFlag(rm, LIGHTBIT))) {
    return false;
  } else if ((rm == SHACK || rm == INSIDE_GATE) || (rm == PEBBLED_PATH || rm == COURTYARD_1) || (rm == COURTYARD_2 || rm == COURTYARD_3 || rm == COURTYARD_4) || (rm == COURTYARD_5 || rm == COURTYARD_6 || rm == COURTYARD_7) || (rm == SHACK_ROOM || rm == BEDROOM)) {
    return false;
  } else {
    return true;
  }
}

async function I_SCURRY() {
  let $1, $2;
  enable(await QUEUE(I_SCURRY.id, 15 + random(20)));
  if (25 > random(100)) {
    if (await OUTSIDE$(g.HERE)) {
      if ((g.NIGHTFALL < 70) && (50 > random(100))) {
        tell("You hear noises in the brambles. Snorting noises are followed by loud crashing and finally a hideous squeal of triumph.\n");
        return true;
      } else {
        tell("You hear a rustling in the brambles nearby, and you catch a glimpse of something small and furry as it scurries away.\n");
        return true;
      }
    } else if ((g.HERE == PIT || g.HERE == REAL_STAIR || g.HERE == PURLOINED_ROOM) || (g.HERE == WARLOCK_TOWER)) {
      return false;
    } else if (getProp(g.HERE, P.TMAZE)) {
      return false;
    } else if (eq(loc(g.WINNER), DUNGEON, NORTH_CELL) || eq(loc(g.WINNER), SECRET_PASSAGE)) {
      tell("You hear, almost beyond your hearing, the soft rattle of chains, and a cold wind blows over the back of your neck.\n");
      return true;
    } else if (g.TOD > g.NIGHTFALL) {
      $1 = await PICK_ONE(g.NIGHT_GLIMPSES);
      tell(S($1));
      tell("\n");
      return true;
    } else {
      $2 = await PICK_ONE(g.GLIMPSES);
      tell(S($2));
      tell("\n");
      return true;
    }
  } else {
    return false;
  }
}

async function GLIMPSE_F() {
  if (g.MOVES > 0) {
    tell("You can't see that anymore.\n");
    return true;
  } else {
    tell("You see no such thing.\n");
    return true;
  }
}

